let aiResponse = $input.first().json.text || $input.first().json.output;

// تنظيف النص من وسوم Markdown وأي مسافات أو أسطر إضافية
aiResponse = aiResponse
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

// محاولة التحليل بشكل آمن
let parsed;
try {
  parsed = JSON.parse(aiResponse);
} catch (error) {
  try {
    // إذا فشل، جرّب استخراج JSON باستخدام regex
    const match = aiResponse.match(/\{[\s\S]*\}/);
    if (match) {
      parsed = JSON.parse(match[0]);
    }
  } catch (innerError) {
    parsed = null;
  }
}

if (parsed && typeof parsed === 'object') {
  return {
    application_id: $('Webhook').first().json.body.application_id,
    score: Math.min(100, Math.max(0, parseInt(parsed.score))),
    reason: parsed.reason || 'لا يوجد تفاصيل'
  };
} else {
  return {
    application_id: $('Webhook').first().json.body.application_id,
    score: 0,
    reason: 'فشل في تحليل التطابق'
  };
}

let text = $input.first().json.text || $input.first().json.output;
