// تنظيف رد الذكاء الاصطناعي واستخراج JSON صالح
let aiResponse = $input.first().json.text || $input.first().json.output || '';

// إزالة أي علامات Markdown
aiResponse = aiResponse.replace(/```json/g, '').replace(/```/g, '').trim();

// محاولة إيجاد JSON داخل النص
const jsonMatch = aiResponse.match(/\{[\s\S]*\}/);
if (jsonMatch) {
  aiResponse = jsonMatch[0];
}

try {
  const parsed = JSON.parse(aiResponse);

  // التأكد من وجود الحقول المطلوبة
  const result = {
    success: true,
    overall_score: Math.min(100, Math.max(0, parseInt(parsed.overall_score) || 0)),
    evaluation: Array.isArray(parsed.evaluation) ? parsed.evaluation.map((e, i) => ({
      question_index: e.question_index !== undefined ? e.question_index : i,
      score: Math.min(10, Math.max(0, parseInt(e.score) || 0)),
      max: 10,
      feedback: e.feedback || 'لا يوجد تعليق'
    })) : [],
    recommendation: parsed.recommendation || 'لا توجد توصية'
  };

  return result;

} catch (error) {
  // في حالة فشل تحليل JSON، أرجع نتيجة افتراضية
  return {
    success: false,
    overall_score: 0,
    evaluation: [],
    recommendation: 'فشل في تحليل نتائج التقييم - يرجى المحاولة مرة أخرى'
  };
}

// تنظيف رد الذكاء الاصطناعي واستخراج JSON صالح
let aiResponse = $input.first().json.text || $input.first().json.output || '';

// إزالة أي علامات Markdown
aiResponse = aiResponse.replace(/```json/g, '').replace(/```/g, '').trim();

// محاولة إيجاد JSON داخل النص
const jsonMatch = aiResponse.match(/\{[\s\S]*\}/);
if (jsonMatch) {
  aiResponse = jsonMatch[0];
}

try {
  const parsed = JSON.parse(aiResponse);

  return {
    success: true,
    average_score: Math.min(100, Math.max(0, parseInt(parsed.average_score) || 0)),
    median_score: Math.min(100, Math.max(0, parseInt(parsed.median_score) || 0)),
    recommendation: parsed.recommendation || 'لا توجد توصية',
    outliers: Array.isArray(parsed.outliers) ? parsed.outliers : [],
    summary: parsed.summary || 'لا يوجد ملخص'
  };

} catch (error) {
  // حساب يدوي في حالة فشل AI
  const scores = $('Webhook3').first().json.body.scores || [];
  const values = scores.map(s => s.score);
  const avg = values.length > 0 ? Math.round(values.reduce((a, b) => a + b, 0) / values.length) : 0;

  return {
    success: true,
    average_score: avg,
    median_score: avg,
    recommendation: avg >= 75 ? 'تأهيل المرشح للعرض الوظيفي' : 'يحتاج مراجعة إضافية',
    outliers: [],
    summary: `تم تقييم المرشح من ${values.length} أعضاء. المتوسط ${avg}%.`
  };
}

